import { modules, sidebarOrder, moduleForPath } from './modules.js';
import { duaaCollections, duaaOrder, orderedItems, isComplete, completedCount, worshipToday, weekStatus, readingPreferences } from './duaa.js';
import { APP_VERSION } from './version.js';
import { sourcesByIds } from './data/source-library.js';
import { resourcesByIds } from './data/resource-library.js';

const esc=(v='')=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const routeParts=(p)=>p.split('/').filter(Boolean);
const isReader=(p)=>/^\/duaa\/[^/]+\/read\/[^/]+(?:\/study\/[^/]+)?\/?$/.test(p)||/^\/quran\/(?:reading-unit|classic|special-readings\/kahf)\//.test(p)||p==='/ramadan/reading';

function sidebar(active){return `<nav class="sidebar-nav" aria-label="Primary navigation">${sidebarOrder.map(id=>{const x=modules[id],a=x.id===active.id;return `<a class="sidebar-link${a?' is-active':''}" href="${x.navigation[0].route}" data-route>${x.icon}<span>${esc(x.shortLabel)}</span></a>`}).join('')}</nav>`}
function moduleNav(active,pathname){return `<nav class="module-nav-bar" aria-label="${esc(active.label)} navigation">${active.navigation.map(item=>{let a=pathname===item.route||(item.route==='/duaa'&&pathname==='/duaa');if(item.route==='/duaa/collections'&&['travel','weather','prayer','istikharah','food','clothing','anxiety'].some(id=>pathname===`/duaa/${id}`||pathname.startsWith(`/duaa/${id}/`)))a=true;if(['/duaa/morning','/duaa/evening','/duaa/sleep'].includes(item.route)&&pathname.startsWith(item.route+'/'))a=true;return `<a class="module-nav-link${a?' is-active':''}" href="${item.route}" data-route>${esc(item.label)}</a>`}).join('')}</nav>`}

function infoTip(label,text){return `<span class="info-tip"><button type="button" class="info-tip-button" aria-label="${esc(label)}">i</button><span class="info-tip-bubble" role="tooltip">${esc(text)}</span></span>`}
function pageEpigraph({quote='',citation='',context='',detail='',externalLink=''}={}){
  if(!quote||!citation)return '';
  const citationLines=Array.isArray(citation)?citation:[citation];
  const externalUrl=typeof externalLink==='string'?externalLink:externalLink?.url||'';
  const externalLabel=typeof externalLink==='object'&&externalLink?.label?externalLink.label:'Source';
  const external=externalUrl?`<p class="page-epigraph-source"><a class="page-epigraph-link" href="${esc(externalUrl)}" target="_blank" rel="noopener noreferrer"><span>${esc(externalLabel)}</span><i class="ph ph-arrow-square-out" aria-hidden="true"></i><span class="sr-only"> (opens in a new tab)</span></a></p>`:'';
  return `<aside class="page-epigraph" aria-label="Page introduction quotation"><blockquote>${context?`<p class="page-epigraph-context">${esc(context)}</p>`:''}<p class="page-epigraph-quote">${esc(quote)}</p><div class="page-epigraph-citation">${citationLines.filter(Boolean).map(line=>`<cite>${esc(line)}</cite>`).join('')}</div>${detail?`<p class="page-epigraph-detail">${esc(detail)}</p>`:''}${external}</blockquote><div class="page-epigraph-divider" aria-hidden="true"><span></span><svg viewBox="0 0 24 24" focusable="false"><path d="M12 2.75 14.15 7l4.6-1.75L17 9.85 21.25 12 17 14.15l1.75 4.6L14.15 17 12 21.25 9.85 17l-4.6 1.75L7 14.15 2.75 12 7 9.85l-1.75-4.6L9.85 7 12 2.75Z"/><circle cx="12" cy="12" r="2.2"/></svg><span></span></div></aside>`;
}
const DUAA_EPIGRAPHS={
  morning:{context:'Morning remembrance was the daily nourishment of the righteous.',quote:'"This is my breakfast. If I do not take my breakfast, I would not have strength to work that day."',citation:'Shaykh al-Islam Ibn Taymiyyah',detail:'As related by Ibn al-Qayyim and explained by Shaykh Salih al-Fawzan.',externalLink:{label:'Source: His Nourishment Was the Remembrance of Allah',url:'https://thewayofsalafiyyah.com/2015/06/14/his-nourishment-was-the-remembrance-of-allah-a-reminder-by-shaykh-fawzan/'}},
  evening:{quote:'"The example of the one who remembers his Lord and the one who does not remember his Lord is like the example of the living and the dead."',citation:['Prophet Muhammad ﷺ','Sahih al-Bukhari']},
  sleep:{quote:'"When you go to bed, perform ablution as you do for prayer, then lie down on your right side..."',citation:['Prophet Muhammad ﷺ','Sahih al-Bukhari & Sahih Muslim']},
  travel:{quote:'"Glorified is He Who has subjected this to us, and we could never have accomplished it by ourselves. And indeed, to our Lord we will surely return."',citation:'Qur’an 43:13–14'},
  weather:{quote:'"O Allah, I ask You for its goodness, the goodness within it, and the goodness with which it has been sent..."',citation:['Prophet Muhammad ﷺ','Sahih Muslim']},
  prayer:{quote:'"The closest that a servant comes to his Lord is while he is in prostration, so increase your supplications therein."',citation:['Prophet Muhammad ﷺ','Sahih Muslim']},
  food:{quote:'"O young boy! Mention Allah’s Name, eat with your right hand, and eat from what is nearest to you."',citation:['Prophet Muhammad ﷺ','Sahih al-Bukhari & Sahih Muslim']},
  clothing:{quote:'"Whoever puts on a garment and says: ‘Praise is to Allah Who clothed me with this and provided it for me without any strength or power on my part,’ his previous sins will be forgiven."',citation:['Prophet Muhammad ﷺ','Sunan Abi Dawud','Jami’ al-Tirmidhi']},
  anxiety:{quote:'"Unquestionably, by the remembrance of Allah hearts find rest."',citation:'Qur’an 13:28'},
  collections:{quote:'"Your Lord says: ‘Call upon Me; I will respond to you.’"',citation:'Qur’an 40:60'},
  history:{quote:'"The most beloved deeds to Allah are those that are consistent, even if they are few."',citation:['Prophet Muhammad ﷺ','Sahih al-Bukhari & Sahih Muslim']}
};
function trackedCard(c){const count=completedCount(c.id),today=worshipToday(c.id);return `<article class="duaa-home-card"><div class="duaa-home-card-top"><span class="collection-type">Tracked daily</span><span class="home-status${today?' is-done':''}">${today?'Recorded today':'Not recorded today'}</span></div><div class="tracked-card-title"><img src="assets/duaa-${c.id}.svg" alt=""><h3>${esc(c.label)}</h3></div><p>${esc(c.intro)}</p><div class="mini-progress" aria-label="${count} of ${c.items.length} completed"><span style="width:${(count/c.items.length)*100}%"></span></div><div class="duaa-card-actions"><a class="button button-secondary" href="/duaa/${c.id}" data-route>Open Collection</a><button class="button ${today?'button-secondary is-done':'button-primary'}" type="button" data-toggle-worship="${c.id}" aria-pressed="${today}">${today?'✓ Done Today':'✓ Mark Done'}</button></div><div class="duaa-card-footer"><span>${count} of ${c.items.length} completed</span></div><div class="card-consistency"><div class="card-consistency-heading"><span>Weekly consistency ${infoTip('About weekly consistency','A day counts when you complete at least one duaa from this collection. Your collection progress is tracked separately.')}</span><a href="/duaa/history" data-route>View History</a></div>${week(c)}</div></article>`}
const collectionIndexImage=(id)=>id==='istikharah'?`assets/duaa-istikharah.svg`:`assets/collection-index-images-v3411/${id}.jpg`;
const homeCollectionImage=(id)=>id==='istikharah'?`assets/duaa-istikharah.svg`:`assets/duaa-home-card-images-v3411/${id}.jpg`;
function collectionArt(id){return `<div class="collection-art collection-art-${id}${id==='istikharah'?' is-fallback':''}" aria-hidden="true"><img src="${homeCollectionImage(id)}" alt=""></div>`}
function untrackedCard(c){return `<article class="collection-library-card">${collectionArt(c.id)}<div class="collection-library-copy"><span class="collection-type">Browse and read</span><h3>${esc(c.label)}</h3><p>${esc(c.intro)}</p><a href="/duaa/${c.id}" data-route>Open collection →</a></div></article>`}
function collectionListItem(c){const label=c.navLabel||c.label.replace(/ Duaas$/,'');return `<a class="collection-index-item" href="/duaa/${c.id}" data-route><span class="collection-index-image${c.id==='istikharah'?' is-fallback':''}"><img src="${collectionIndexImage(c.id)}" alt=""></span><span class="collection-index-copy"><strong>${esc(label)}</strong><span>${esc(c.intro)}</span></span><i class="ph ph-caret-right collection-index-caret" aria-hidden="true"></i></a>`}
function duaaHome(){const tracked=duaaOrder.map(id=>duaaCollections[id]).filter(c=>c.tracked);const homeCollectionIds=new Set(['travel','weather','prayer','istikharah']);const other=duaaOrder.map(id=>duaaCollections[id]).filter(c=>!c.tracked&&homeCollectionIds.has(c.id));return `<section class="duaa-landing">${pageEpigraph(DUAA_EPIGRAPHS.collections)}<section class="home-section"><div class="section-heading"><div><p class="section-eyebrow">Daily companion</p><h3>Tracked collections</h3></div></div><div class="duaa-home-grid">${tracked.map(trackedCard).join('')}</div></section><section class="home-section"><div class="section-heading"><div><p class="section-eyebrow">More collections</p><h3>Browse by situation</h3></div><a class="section-link" href="/duaa/collections" data-route>View all collections →</a></div><div class="collection-library-grid is-compact">${other.map(untrackedCard).join('')}</div></section></section>`}
function week(c){return `<div class="week-row" aria-label="Weekly consistency">${weekStatus(c.id).map(d=>`<div class="week-day${d.active?' is-active':''}${d.today?' is-today':''}"><span>${d.label}</span><i aria-hidden="true"></i></div>`).join('')}</div>`}
function progressPanel(c){const count=completedCount(c.id),pct=Math.round(count/c.items.length*100),done=worshipToday(c.id);return `<aside class="progress-panel"><p class="panel-eyebrow">Today’s status</p><div class="today-status${done?' is-done':''}" role="status"><i class="ph ph-${done?'check-circle-fill':'circle'}" aria-hidden="true"></i><div><strong>${done?'Recorded today':'Not recorded'}</strong><span>${done?'At least one duaa counted today.':'One duaa is enough to count today.'}</span></div></div><button class="button button-primary worship-button${done?' is-recorded':''}" type="button" data-toggle-worship="${c.id}" aria-pressed="${done}">${done?'✓ Recorded for Today':'Record Today'}</button><div class="progress-summary" aria-label="Collection progress"><div><span>Collection progress</span><strong>${count} of ${c.items.length}</strong></div><div class="collection-progress"><span style="width:${pct}%"></span></div><small>${pct}% completed in the app</small></div><div class="weekly-block"><div class="weekly-heading"><span>Weekly consistency</span><a href="/duaa/history" data-route>View History</a></div>${week(c)}</div></aside>`}
function collectionList(c){const items=orderedItems(c.id);return `<div class="collection-list" data-collection-list="${c.id}">${items.map(d=>{const done=c.tracked&&isComplete(c.id,d.id);return `<article class="duaa-index-row${done?' is-complete':''}" id="duaa-${esc(d.id)}" draggable="false" data-duaa-row="${d.id}"><button class="reorder-handle" type="button" title="Drag to reorder ${esc(d.title)}" aria-label="Drag to reorder ${esc(d.title)}" data-drag-handle><svg viewBox="0 0 16 24" width="16" height="24" aria-hidden="true" focusable="false"><circle cx="5" cy="6" r="1.5"></circle><circle cx="11" cy="6" r="1.5"></circle><circle cx="5" cy="12" r="1.5"></circle><circle cx="11" cy="12" r="1.5"></circle><circle cx="5" cy="18" r="1.5"></circle><circle cx="11" cy="18" r="1.5"></circle></svg></button>${c.tracked?`<button class="row-state" type="button" data-toggle-complete="${c.id}:${d.id}" aria-pressed="${done}" aria-label="${done?'Remove completion from':'Mark complete'} ${esc(d.title)}"><i class="ph ph-check" aria-hidden="true"></i></button>`:'<span class="row-state is-empty" aria-hidden="true"></span>'}<div class="row-copy"><h3>${esc(d.title)}</h3><p>${esc(d.subtitle)}</p></div><a class="read-link" href="/duaa/${c.id}/read/${d.id}" data-route>Read <span aria-hidden="true">→</span></a></article>`}).join('')}</div>`}
function collectionPage(c){
  const epigraph=DUAA_EPIGRAPHS[c.id]||{quote:`“${c.quote}”`,citation:c.quoteSource};
  const collectionBody=c.items.length
    ?`${collectionList(c)}`
    :`<div class="collection-empty-state"><i class="ph ph-book-open-text" aria-hidden="true"></i><h4>Collection page ready</h4><p>The page and banner are in place. Verified duaa entries can be added in the dedicated content pass.</p><a href="/duaa/collections" data-route>Return to Collections</a></div>`;
  return `<section class="collection-page">${pageEpigraph(epigraph)}<div class="collection-layout${c.tracked?'':' is-untracked'}">${c.tracked?progressPanel(c):''}<section class="collection-main"><div class="collection-heading"><div><p class="section-eyebrow">Collection</p><h3>${c.items.length} ${c.items.length===1?'duaa':'duaas'}</h3></div>${c.items.length?`<div class="collection-tools">${infoTip('How to reorder duaas','Drag the six-dot handle to arrange these duaas in the order you prefer.')}</div>`:''}</div>${collectionBody}</section></div></section>`;
}

function collectionsPage(){const collections=duaaOrder.map(id=>duaaCollections[id]).filter(Boolean).sort((a,b)=>(a.navLabel||a.label).localeCompare(b.navLabel||b.label));return `<section class="collections-page">${pageEpigraph(DUAA_EPIGRAPHS.collections)}<nav class="collection-index" aria-label="Duaa collections">${collections.map(collectionListItem).join('')}</nav></section>`}
const studyGroups=[['Audio','audio','headphones','Lectures and explanations'],['Articles','article','file-text','Authentic articles and benefits'],['Videos','video','video-camera','Selected video reminders'],['Books','book','book-open','Recommended reading'],['Tweets / Posts','tweet','chat-circle-dots','Short reminders and threads']];
function itemResources(item,type){const linked=resourcesByIds(item.resourceIds||[]);const fallback=Array.isArray(item.resources)?item.resources:[];return (linked.length?linked:fallback).filter(resource=>String(resource.type||'').toLowerCase()===type)}
function studyLibrary(c,item){return `<section class="reader-study"><div class="study-divider" aria-hidden="true"></div><div class="reader-study-heading"><span class="study-heading-icon"><i class="ph ph-book-open" aria-hidden="true"></i></span><div><h3>Study Library</h3><p>Continue learning with trusted resources related to this duaa.</p></div></div><div class="study-category-list">${studyGroups.map(([label,type,icon,desc])=>{const resources=itemResources(item,type),count=resources.length;return `<details class="study-accordion"><summary class="study-category"><span class="study-category-icon"><i class="ph ph-${icon}" aria-hidden="true"></i></span><span class="study-category-copy"><strong>${label}</strong><small>${desc}</small></span><b>${count}</b><i class="ph ph-caret-down study-caret" aria-hidden="true"></i></summary><div class="study-accordion-panel">${resources.length?`<div class="resource-list is-inline">${resources.map(resource=>`<a class="resource-row" href="${esc(resource.url||resource.link||'#')}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(resourceTitle(resource))}</strong><small>${esc(resourceMeta(resource))}</small></span>${resource.duration?`<em>${esc(resource.duration)}</em>`:''}<i class="ph ph-arrow-square-out" aria-hidden="true"></i></a>`).join('')}</div>`:`<div class="study-empty is-inline"><p>No ${label.toLowerCase()} resources have been added yet.</p></div>`}</div></details>`}).join('')}</div><p class="external-note"><i class="ph ph-info" aria-hidden="true"></i> Resources open in a new tab. Ummiby Companion does not host or control external content.</p></section>`}
function readingSettings(prefs){return `<dialog class="reading-settings" data-reading-dialog><form method="dialog"><header><div><p class="section-eyebrow">Reading display</p><h2>Reading Preferences</h2></div><button class="dialog-close" value="close" aria-label="Close reading preferences">×</button></header><label class="range-field" for="arabic-size"><span>Arabic text size</span><input id="arabic-size" type="range" min="1.7" max="3.4" step="0.1" value="${prefs.arabicSize}" data-reading-size><output data-size-output>${prefs.arabicSize.toFixed(1)}rem</output></label><fieldset><legend>Display</legend><label class="check-row"><input type="checkbox" data-reading-transliteration ${prefs.showTransliteration?'checked':''}><span>Transliteration</span></label><label class="check-row"><input type="checkbox" data-reading-english ${prefs.showEnglish?'checked':''}><span>English translation</span></label></fieldset><button class="button button-primary" value="close">Done</button></form></dialog>`}
function sourceLink(source,label='View source'){
  if(!source) return '';
  if(source.url) return `<a class="evidence-link" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <i class="ph ph-arrow-square-out" aria-hidden="true"></i></a>`;
  return `<span class="evidence-link is-pending" title="A verified destination link has not been added yet.">${esc(source.citation)} <span>Link pending</span></span>`;
}
function readerEvidence(item){
  const sources=sourcesByIds(item.sourceIds||[]),virtueSources=sourcesByIds(item.virtue?.sourceIds||[]);
  return `<section class="reader-evidence" aria-label="Duaa evidence and benefit">${item.virtue?.text?`<article class="evidence-card virtue-card"><div class="evidence-heading"><span class="evidence-icon"><i class="ph ph-sparkle" aria-hidden="true"></i></span><div><p class="section-eyebrow">Virtue</p><h3>Benefit of this duaa</h3></div></div><p>${esc(item.virtue.text)}</p>${virtueSources.length?`<div class="evidence-links">${virtueSources.map(source=>sourceLink(source,`View ${source.citation}`)).join('')}</div>`:''}</article>`:''}<article class="evidence-card source-card"><div class="evidence-heading"><span class="evidence-icon"><i class="ph ph-books" aria-hidden="true"></i></span><div><p class="section-eyebrow">Evidence</p><h3>${sources.length===1?'Source':'Sources'}</h3></div></div><div class="source-citations">${sources.length?sources.map(source=>sourceLink(source,source.citation)).join(''):`<span>${esc(item.source||'Source pending')}</span>`}</div>${item.sourceDetails?.grade?`<span class="source-grade">${esc(item.sourceDetails.grade)}</span>`:''}</article></section>`;
}
function readerSegments(item,prefs){
  const segments=Array.isArray(item.segments)&&item.segments.length?item.segments:(item.focusPhrases||[]).map(segment=>({arabic:segment.arabic,english:segment.translation,transliteration:segment.transliteration}));
  const layoutClass=!prefs.showTransliteration&&!prefs.showEnglish?' is-arabic-only':(!prefs.showTransliteration||!prefs.showEnglish?' is-two-column':'');
  return `<section class="duaa-learning${layoutClass}" aria-label="Duaa learning view"><div class="learning-grid learning-grid-heading" aria-hidden="true">${prefs.showTransliteration?'<span>Transliteration</span>':''}${prefs.showEnglish?'<span>English</span>':''}<span>Arabic</span></div>${segments.map((segment,index)=>`<article class="learning-segment"><span class="segment-number">${index+1}</span><div class="learning-grid">${prefs.showTransliteration?`<p class="segment-transliteration"><span class="mobile-segment-label">Transliteration</span>${segment.transliteration?esc(segment.transliteration):'<span class="segment-missing">Transliteration not yet added</span>'}</p>`:''}${prefs.showEnglish?`<p class="segment-english"><span class="mobile-segment-label">English</span>${esc(segment.english)}</p>`:''}<p class="segment-arabic" lang="ar" dir="rtl"><span class="mobile-segment-label">Arabic</span>${esc(segment.arabic)}</p></div></article>`).join('')}</section>`;
}
function readerPage(c,item){const items=orderedItems(c.id),i=items.findIndex(x=>x.id===item.id),prefs=readingPreferences();return `<section class="reader-page" style="--reader-arabic-size:${prefs.arabicSize}rem"><header class="reader-top"><a class="reader-exit" href="/duaa/${c.id}" data-route data-exit-reader>← Exit Reading Mode</a><div class="reader-position"><span>${esc(c.label)}</span><strong>${i+1} of ${items.length}</strong></div><button class="reader-settings-button" type="button" data-reading-settings aria-label="Open reading preferences"><i class="ph ph-gear" aria-hidden="true"></i></button></header><article class="reader-content"><header class="duaa-reader-heading"><div><p class="reader-kicker">${esc(c.label)}</p><h1>${esc(item.title)}</h1>${item.subtitle?`<p>${esc(item.subtitle)}</p>`:''}</div><span class="repeat-badge"><small>Recite</small><strong>${esc(item.repeat||item.count||'1x')}</strong></span></header>${readerSegments(item,prefs)}${readerEvidence(item)}${studyLibrary(c,item)}</article><nav class="reader-controls" aria-label="Reading controls">${i>0?`<a href="/duaa/${c.id}/read/${items[i-1].id}" data-route>← Previous</a>`:'<span></span>'}${c.tracked?`<button class="button ${isComplete(c.id,item.id)?'button-secondary':'button-primary'}" type="button" data-toggle-complete="${c.id}:${item.id}">${isComplete(c.id,item.id)?'✓ Completed':'Mark Complete'}</button>`:'<span></span>'}${i<items.length-1?`<a href="/duaa/${c.id}/read/${items[i+1].id}" data-route>Next →</a>`:'<span></span>'}</nav>${readingSettings(prefs)}</section>`}
function resourceTitle(resource){return resource.title||resource.name||resource.label||'Study resource'}
function resourceMeta(resource){return resource.author||resource.speaker||resource.source||''}
function studyCategoryPage(c,item,type){const group=studyGroups.find(x=>x[1]===type)||studyGroups[0],resources=itemResources(item,type);return `<section class="study-detail-page"><header class="reader-top"><a href="/duaa/${c.id}/read/${item.id}" data-route>← Back to Study Library</a><div class="reader-position"><span>${esc(c.label)}</span><strong>${esc(item.title)}</strong></div></header><main class="study-detail-content"><div class="study-detail-heading"><span class="study-heading-icon"><i class="ph ph-${group[2]}" aria-hidden="true"></i></span><div><p class="section-eyebrow">Study Library</p><h2>${group[0]} Resources</h2><p>${group[3]} related to this duaa.</p></div><span class="resource-count">${resources.length} ${resources.length===1?'resource':'resources'}</span></div>${resources.length?`<div class="resource-list">${resources.map(resource=>`<a class="resource-row" href="${esc(resource.url||resource.link||'#')}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(resourceTitle(resource))}</strong><small>${esc(resourceMeta(resource))}</small></span>${resource.duration?`<em>${esc(resource.duration)}</em>`:''}<i class="ph ph-arrow-square-out" aria-hidden="true"></i></a>`).join('')}</div>`:`<div class="study-empty"><i class="ph ph-books" aria-hidden="true"></i><h3>No ${group[0].toLowerCase()} resources yet</h3><p>This category is ready for trusted resources when they are added.</p></div>`}<p class="external-note"><i class="ph ph-info" aria-hidden="true"></i> Resources open in a new tab. Ummiby Companion does not host or control external content.</p></main></section>`}
function history(){return `<section>${pageEpigraph(DUAA_EPIGRAPHS.history)}<div class="history-grid">${['morning','evening','sleep'].map(id=>{const c=duaaCollections[id];return `<article class="history-card"><h3>${esc(c.label)}</h3>${week(c)}<p>${worshipToday(id)?'Recorded today':'Not yet recorded today'}</p></article>`}).join('')}</div></section>`}
function settings(){return `<section><header class="editorial-header"><p class="page-kicker">Duaa preferences</p><h2>Settings</h2><p>Collection-specific reading and Arabic display controls will live here as the module expands.</p></header><article class="settings-placeholder"><h3>Reading display</h3><p>The new reader uses spacious Arabic, transliteration, meaning, and source sections. Existing account-wide preferences remain unchanged.</p></article></section>`}
function duaaContent(path){const p=routeParts(path);if(path==='/duaa')return duaaHome();if(path==='/duaa/collections')return collectionsPage();if(path==='/duaa/history')return history();const c=duaaCollections[p[1]];if(!c)return `<section class="empty-state"><h2>Collection not found</h2><a href="/duaa" data-route>Return to Duaa Home</a></section>`;if(p[2]==='read'){const items=orderedItems(c.id);const item=items.find(x=>x.id===p[3])||items[0];if(p[4]==='study'&&p[5])return studyCategoryPage(c,item,p[5]);return readerPage(c,item)}return collectionPage(c)}
function visionIcon(name){return `<span class="vision-icon"><i class="ph ph-${name}" aria-hidden="true"></i></span>`}
function progressBar(value){return `<div class="vision-progress"><span style="width:${value}%"></span></div>`}
function quranHome(){const isFriday=new Date().getDay()===5;const leftFeature=isFriday?`<article class="quran-primary-card friday-primary">${visionIcon('cave')}<div class="primary-card-copy"><p class="section-eyebrow">It’s Friday</p><h3>Read Surah al-Kahf</h3><p>Set aside your regular journey today and begin the Friday reading from ayah 1.</p><div class="primary-card-actions"><a class="button button-primary" href="/quran/special-readings/kahf/1" data-route>Read Surah al-Kahf</a></div></div></article>`:`<article class="quran-primary-card continue-primary">${visionIcon('book-open-text')}<div class="primary-card-copy"><p class="section-eyebrow">Continue Reading</p><h3>Reading Unit Journey</h3><strong>Reading Unit 87</strong><span>Al-Baqarah 253–259</span>${progressBar(29)}<small>87 of 294 units</small><div class="primary-card-actions"><a class="button button-primary" href="/quran/reading-unit/87" data-route>Continue</a><a class="button button-secondary" href="/quran/journeys" data-route>Switch Journey</a></div></div></article>`;return `<section class="vision-page quran-vision"><header class="editorial-header"><p class="page-kicker">Qur’an companion</p><h2>Read, reflect, and return</h2><p>A peaceful place for long-term reading, special recitations, and memorization.</p></header><section class="quran-home-columns"><div class="quran-home-primary">${leftFeature}</div><aside class="quran-home-support"><section class="support-panel weekly-support"><div class="section-heading"><div><p class="section-eyebrow">Every reading counts</p><h3>Weekly Consistency</h3></div><a class="section-link" href="#">View History</a></div><div class="vision-week">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<div><span>${d}</span><i class="${[0,2,3,4].includes(i)?'is-done':''}"></i></div>`).join('')}</div></section><section class="support-panel progress-support"><div class="section-heading"><div><p class="section-eyebrow">Your journey</p><h3>Reading Progress</h3></div></div><div class="progress-summary-list"><article><span>Reading Unit Journey</span><strong>87 <small>/ 294</small></strong>${progressBar(29)}</article><article><span>Classic Journey</span><strong>18 <small>/ 114</small></strong>${progressBar(16)}</article></div></section></aside></section><section class="home-section purpose-section"><div class="section-heading"><div><p class="section-eyebrow">Choose your purpose</p><h3>Explore the Qur’an</h3></div></div><div class="vision-link-grid"><a href="/quran/journeys" data-route>${visionIcon('path')}<span><strong>Reading Journeys</strong><small>Systematic ways to read through the Qur’an.</small></span><i class="ph ph-arrow-right"></i></a><a href="/quran/special-readings" data-route>${visionIcon('sparkle')}<span><strong>Special Readings</strong><small>Recurring recitations for important occasions.</small></span><i class="ph ph-arrow-right"></i></a><a href="/quran/memorization" data-route>${visionIcon('bookmark-simple')}<span><strong>Memorization</strong><small>Learn, review, and track ayat.</small></span><i class="ph ph-arrow-right"></i></a></div></section></section>`}
function journeysPage(){return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Qur’an reading</p><h2>Reading Journeys</h2><p>Two permanent ways to move through the Qur’an, both supported by the shared reading workspace and Study Library.</p></header><div class="journey-grid"><article class="journey-card">${visionIcon('book-open-text')}<div><p class="section-eyebrow">294 balanced units</p><h3>Reading Unit Journey</h3><p>Read connected passages with a short orientation to the topics in each unit.</p>${progressBar(29)}<span class="journey-stat">87 of 294 units complete</span></div><div class="journey-actions"><a class="button button-primary" href="/quran/reading-unit/87" data-route>Continue</a><a class="button button-secondary" href="/quran/reading-units" data-route>Browse Unit Index</a></div></article><article class="journey-card">${visionIcon('books')}<div><p class="section-eyebrow">114 surahs</p><h3>Classic Journey</h3><p>Read the Qur’an in surah order with progress tracked from beginning to end.</p>${progressBar(16)}<span class="journey-stat">18 of 114 surahs complete</span></div><div class="journey-actions"><a class="button button-primary" href="/quran/classic/al-baqarah" data-route>Continue</a><a class="button button-secondary" href="/quran/surahs" data-route>Browse Surah Index</a></div></article></div></section>`}
function specialReadings(){const items=[['cave','Friday Reading','Surah al-Kahf','Featured on Fridays','/quran/special-readings/kahf/1'],['star-four','Ayat al-Kursī','The Throne Verse','Al-Baqarah 2:255','/quran/special-readings/ayat-al-kursi'],['book-open','Last Two Ayat of al-Baqarah','Al-Baqarah 2:285–286','Evening recitation','/quran/special-readings/last-two'],['moon-stars','Surah al-Mulk','The Sovereignty','Night recitation','/quran/special-readings/al-mulk']];return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Recurring recitations</p><h2>Special Readings</h2><p>A curated home for readings connected to particular times, virtues, and practices.</p></header><div class="special-list">${items.map(([ic,k,t,m,r],i)=>`<a class="special-card${i===0?' is-featured':''}" href="${r}" data-route>${visionIcon(ic)}<span><small>${k}</small><strong>${t}</strong><em>${m}</em></span><i class="ph ph-caret-right"></i></a>`).join('')}</div></section>`}
const sampleAyat=[{n:255,en:'Allah—there is no deity except Him, the Ever-Living, the Sustainer of existence. Neither drowsiness overtakes Him nor sleep.',ar:'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ'},{n:256,en:'There is no compulsion in religion. The right course has become clear from the wrong.',ar:'لَا إِكْرَاهَ فِي الدِّينِ ۖ قَد تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ'},{n:257,en:'Allah is the ally of those who believe. He brings them out from darknesses into the light.',ar:'اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُم مِّنَ الظُّلُمَاتِ إِلَى النُّورِ'}];
function ayatRows(ayat=sampleAyat){return `<div class="ayah-list">${ayat.map(a=>`<article class="ayah-row"><div class="ayah-translation"><span class="ayah-number">${a.n}</span><p>${a.en}</p></div><p class="ayah-arabic" lang="ar" dir="rtl">${a.ar} <span class="ayah-marker">${a.n}</span></p></article>`).join('')}</div>`}
function sharedStudy(count=4){const groups=[['Articles','article','Written explanations and study notes'],['Audio','headphones','Lessons and recitations'],['Video','video','Visual lessons and reminders'],['Other','dots-three','Additional trusted resources']];return `<section class="quran-study reader-study"><div class="study-divider" aria-hidden="true"></div><div class="reader-study-heading"><span class="study-heading-icon"><i class="ph ph-book-open" aria-hidden="true"></i></span><div><h3>Study Library <span>(${count})</span></h3><p>Continue learning with trusted resources related to this passage.</p></div></div><div class="study-category-list">${groups.map(([label,icon,desc],i)=>`<details class="study-accordion"><summary class="study-category"><span class="study-category-icon"><i class="ph ph-${icon}" aria-hidden="true"></i></span><span class="study-category-copy"><strong>${label}</strong><small>${desc}</small></span><b>${i===0?count:0}</b><i class="ph ph-caret-down study-caret" aria-hidden="true"></i></summary><div class="study-accordion-panel"><div class="study-empty is-inline"><p>${i===0?'Resources for this passage will appear here.':`No ${label.toLowerCase()} resources have been added yet.`}</p></div></div></details>`).join('')}</div><p class="external-note"><i class="ph ph-info" aria-hidden="true"></i> Resources open in a new tab. Ummiby Companion does not host or control external content.</p></section>`}
function quranReadingSettings(prefs){return `<dialog class="reading-settings quran-reading-settings" data-reading-dialog><form method="dialog"><header><div><p class="section-eyebrow">Reading display</p><h2>Reading Preferences</h2></div><button class="dialog-close" value="close" aria-label="Close reading preferences">×</button></header><label class="range-field" for="quran-arabic-size"><span>Arabic text size</span><input id="quran-arabic-size" type="range" min="1.7" max="3.4" step="0.1" value="${prefs.arabicSize}" data-reading-size><output data-size-output>${prefs.arabicSize.toFixed(1)}rem</output></label><p class="settings-note">English remains beside the Arabic whenever the available screen width allows it.</p><button class="button button-primary" value="close">Done</button></form></dialog>`}
function studyLibraryCue(){return `<a class="study-library-cue" href="#quran-study-library"><span><i class="ph ph-books" aria-hidden="true"></i> Study Library below</span><i class="ph ph-arrow-down" aria-hidden="true"></i></a>`}
function quranReader(mode){const prefs=readingPreferences();let head='',context='',center='Mark Complete',pct=29,progressLabel='of this unit';if(mode==='unit'){head='<span>Reading Unit 87</span><strong>Al-Baqarah 253–259</strong>';context=`<section class="reader-context unit-context"><div class="topic-heading"><p class="section-eyebrow">Topics in this Unit</p><ul class="topic-list"><li>Allah’s sovereignty</li><li>The Throne Verse</li><li>No compulsion in religion</li></ul></div></section>`}if(mode==='classic'){pct=18;progressLabel='of this surah';head='<span>Classic Journey</span><strong>Surah al-Baqarah</strong>';context=`<section class="reader-context compact"><div><p class="section-eyebrow">Surah progress</p><h2>Al-Baqarah</h2><span>Ayah 253 of 286</span></div></section>`;center='<i class="ph ph-bookmark-simple"></i>'}return `<section class="quran-reader" style="--reader-arabic-size:${prefs.arabicSize}rem"><header class="quran-reader-top"><a class="quran-reader-exit" href="/quran" data-route aria-label="Exit Reading Mode and return to Qur’an Home"><i class="ph ph-arrow-left"></i><span>Exit Reading Mode</span></a><div>${head}</div><button type="button" data-reading-settings aria-label="Open reading preferences"><i class="ph ph-gear"></i></button></header>${context}${ayatRows()}${studyLibraryCue()}<div id="quran-study-library">${sharedStudy()}</div><nav class="quran-reader-controls"><div class="reader-control-progress"><span class="reader-progress-label"><strong>${pct}%</strong> ${progressLabel}</span>${progressBar(pct)}</div><div class="reader-control-actions"><a href="#"><i class="ph ph-arrow-left"></i><span>Previous</span></a><button class="reader-center-action button button-primary">${center}</button><a href="#"><span>Next</span><i class="ph ph-arrow-right"></i></a></div></nav>${quranReadingSettings(prefs)}</section>`}
function kahfReader(){const ayat=[{n:9,en:'Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?',ar:'أَمْ حَسِبْتَ أَنَّ أَصْحَابَ الْكَهْفِ وَالرَّقِيمِ كَانُوا مِنْ آيَاتِنَا عَجَبًا'},{n:10,en:'When the young men retreated to the cave and said, “Our Lord! Grant us mercy from Yourself and guide us rightly through our ordeal.”',ar:'إِذْ أَوَى الْفِتْيَةُ إِلَى الْكَهْفِ فَقَالُوا رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا'}];return `<section class="quran-reader kahf-reader"><header class="quran-reader-top"><a href="/quran/special-readings" data-route><i class="ph ph-arrow-left"></i></a><div><span>Friday Reading · Surah al-Kahf</span><strong>The People of the Cave</strong></div><button><i class="ph ph-gear"></i></button></header><section class="story-heading">${visionIcon('cave')}<div><p class="section-eyebrow">Section 2 of 6</p><h2>The People of the Cave</h2><p>Ayat 9–26</p></div></section>${ayatRows(ayat)}${sharedStudy(5)}<nav class="quran-reader-controls"><a href="#"><i class="ph ph-arrow-left"></i><span>Previous</span></a><button class="reader-center-action"><i class="ph ph-bookmark-simple"></i></button><a href="#"><span>Next</span><i class="ph ph-arrow-right"></i></a></nav></section>`}
function memorizationVision(){return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Memorization</p><h2>Your memorization workspace</h2><p>This page remains a simple layout marker for the existing memorization concept.</p></header><div class="vision-two-grid"><article class="metric-card"><span>Currently Memorizing</span><strong>Al-Mulk</strong><p>Ayah 8 of 30</p><a href="#">Continue Memorizing</a></article><article class="metric-card"><span>Needs Revision</span><strong>3 <small>surahs</small></strong><p>Review the ayat that need attention.</p><a href="#">Open Revision</a></article></div><section class="home-section"><div class="section-heading"><div><p class="section-eyebrow">All surahs</p><h3>Surah Library</h3></div></div><div class="placeholder-panel">Search, filters, status cards, and clickable ayah tracking will be developed in a later pass.</div></section></section>`}
function quranContent(path){if(path==='/quran')return quranHome();if(path==='/quran/journeys')return journeysPage();if(path==='/quran/special-readings')return specialReadings();if(path==='/quran/reading-unit/87')return quranReader('unit');if(path==='/quran/classic/al-baqarah')return quranReader('classic');if(path==='/quran/special-readings/kahf/1')return kahfReader();if(path==='/quran/memorization')return memorizationVision();return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Qur’an vision</p><h2>Layout placeholder</h2><p>This route is reserved for the next detailed design pass.</p></header><div class="placeholder-panel"><a href="/quran" data-route>Return to Qur’an Home</a></div></section>`}
function ramadanHome(){return `<section class="vision-page ramadan-vision"><header class="editorial-header"><p class="page-kicker">Ramadan Central</p><h2>Keep the month close</h2><p>The Ramadan Reading Journey belongs here, alongside fasting, duaa, and the final nights.</p></header><section class="vision-feature-card ramadan-reading-card"><div>${visionIcon('book-open-text')}<div><p class="section-eyebrow">Continue Reading</p><h3>Ramadan Reading Journey</h3><p>Day 12 · Juz 12 · ʿAṣr portion</p>${progressBar(40)}</div></div><a class="button button-primary" href="/ramadan/reading" data-route>Continue</a></section><div class="vision-link-grid four"><a href="/ramadan/fasting" data-route>${visionIcon('calendar-check')}<span><strong>Fasting Tracker</strong><small>Record each day.</small></span></a><a href="/ramadan/duaa" data-route>${visionIcon('hands-praying')}<span><strong>Duaa Library</strong><small>Ramadan collections.</small></span></a><a href="#">${visionIcon('sparkle')}<span><strong>Last Ten Nights</strong><small>Nightly focus.</small></span></a><a href="/ramadan/history" data-route>${visionIcon('archive')}<span><strong>Ramadan History</strong><small>Past years.</small></span></a></div></section>`}
function ramadanReader(){return `<section class="quran-reader ramadan-reader"><header class="quran-reader-top"><a href="/ramadan" data-route><i class="ph ph-arrow-left"></i></a><div><span>Ramadan Reading Journey</span><strong>Day 12 · Juz 12 · ʿAṣr Portion</strong></div><button><i class="ph ph-gear"></i></button></header><section class="reader-context compact"><div><p class="section-eyebrow">Today’s reading</p><h2>ʿAṣr Portion</h2><span>Part 4 of 5 · Day 12</span></div>${progressBar(48)}</section>${ayatRows()}${sharedStudy()}<nav class="quran-reader-controls"><a href="#"><i class="ph ph-arrow-left"></i><span>Previous</span></a><button class="reader-center-action">Mark Complete</button><a href="#"><span>Next</span><i class="ph ph-arrow-right"></i></a></nav></section>`}
function ramadanContent(path){if(path==='/ramadan')return ramadanHome();if(path==='/ramadan/reading')return ramadanReader();return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Ramadan Central</p><h2>Layout placeholder</h2><p>This area remains available for the existing Ramadan blueprint.</p></header><div class="placeholder-panel"><a href="/ramadan" data-route>Return to Ramadan Home</a></div></section>`}

function placeholders(active){if(active.id==='home')return sidebarOrder.filter(id=>!['home','settings'].includes(id)).map(id=>{const x=modules[id];return `<article class="card"><span class="status-pill">Foundation registered</span><h2>${esc(x.label)}</h2><p>${esc(x.description)}</p><a href="${x.navigation[0].route}" data-route>Open ${esc(x.label)}</a></article>`}).join('');return `<article class="card"><span class="status-pill">v${APP_VERSION} foundation</span><h2>Module shell is ready</h2><p>This module remains a placeholder while Duaa receives its first complete collection and reading experience.</p></article>`}
function bannerMeta(active,path){
  const duaaBanners={
    '/duaa':{eyebrow:'DUAA',title:'Duaa Home',description:'Authentic supplications for every stage of your day.'},
    '/duaa/morning':{eyebrow:'DUAA',title:'Morning Duaas',description:'Begin your day with authentic remembrance.'},
    '/duaa/evening':{eyebrow:'DUAA',title:'Evening Duaas',description:'Close your day with authentic remembrance.'},
    '/duaa/sleep':{eyebrow:'DUAA',title:'Before Sleep Duaas',description:'End your day with remembrance, protection, and trust in Allah.'},
    '/duaa/travel':{eyebrow:'DUAA',title:'Travel Duaas',description:'Remember Allah as you set out, travel, stop, and return.'},
    '/duaa/weather':{eyebrow:'DUAA',title:'Weather Duaas',description:'Remember Allah through rain, wind, storms, and changing skies.'},
    '/duaa/prayer':{eyebrow:'DUAA',title:'Prayer Duaas',description:'Supplications connected to the masjid, prayer, and seeking guidance.'},
    '/duaa/collections':{eyebrow:'DUAA',title:'Collections',description:'Explore authentic supplications for every time and situation.'},
    '/duaa/history':{eyebrow:'DUAA',title:'History',description:'Reflect on your journey of remembrance.'},
    '/duaa/food':{eyebrow:'DUAA',title:'Food & Drink Duaas',description:'Remember Allah before, during, and after eating and drinking.'},
    '/duaa/clothing':{eyebrow:'DUAA',title:'Clothing Duaas',description:'Remember Allah when dressing and receiving new clothing.'},
    '/duaa/anxiety':{eyebrow:'DUAA',title:'Anxiety & Sadness Duaas',description:'Turn to Allah through worry, grief, distress, and sadness.'}
  };
  return duaaBanners[path]||{eyebrow:active.bannerEyebrow,title:active.bannerTitle,description:active.description};
}
function viewName(active,path){if(active.id==='duaa'){const p=routeParts(path),c=duaaCollections[p[1]];if(p[2]==='read')return c?.label||'Reading';if(c)return c.label;if(path==='/duaa/collections')return'Collections';if(path==='/duaa/history')return'History';}if(active.id==='quran'){if(path.includes('/reading-unit/'))return'Reading Unit';if(path.includes('/classic/'))return'Classic Journey';if(path.includes('/special-readings/kahf/'))return'Friday Reading';}if(active.id==='ramadan'&&path==='/ramadan/reading')return'Ramadan Reading Journey';return active.navigation.find(x=>x.route===path)?.label||active.navigation[0].label}
function accountName(identity,user){return identity?.fullName||user?.user_metadata?.full_name||user?.user_metadata?.name||user?.email?.split('@')[0]||'My Account'}
function accountInitials(name,email){const source=String(name||email||'U').trim();const words=source.split(/\s+/).filter(Boolean);return esc((words.length>1?`${words[0][0]}${words.at(-1)[0]}`:source.slice(0,2)).toUpperCase())}
function formatAccountDate(value){if(!value)return 'Not available';const date=new Date(value);return Number.isNaN(date.getTime())?'Not available':date.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
function accountControls(user,identity,configured){
  const isAuthenticated=Boolean(user);
  const name=isAuthenticated?accountName(identity,user):"Preview Mode";
  const email=isAuthenticated?(identity?.email||user?.email||""):"Supabase is not configured";
  const initials=isAuthenticated?accountInitials(name,email):"LP";
  const sessionAction=isAuthenticated
    ? `<div class="account-menu-divider"></div><button class="account-sign-out" type="button" role="menuitem" data-request-sign-out><i class="ph ph-sign-out" aria-hidden="true"></i><span>Sign Out</span></button>`
    : `<p class="account-preview-note"><i class="ph ph-info" aria-hidden="true"></i><span>Account details and Sign Out become active when the app is connected to Supabase.</span></p>`;
  const profileDetails=isAuthenticated
    ? `<dl class="account-details"><div><dt>Display name</dt><dd>${esc(name)}</dd></div><div><dt>Email</dt><dd>${esc(email)}</dd></div><div><dt>Account created</dt><dd>${esc(formatAccountDate(user?.created_at))}</dd></div><div><dt>Last sign in</dt><dd>${esc(formatAccountDate(user?.last_sign_in_at))}</dd></div></dl><p class="dialog-note">Profile editing will be added when account settings are expanded.</p>`
    : `<div class="account-empty-state"><i class="ph ph-user-circle" aria-hidden="true"></i><h3>Preview Mode</h3><p>Supabase is not configured. The account controls remain visible so the application shell can be reviewed locally.</p></div>`;
  return `<div class="account-control"><button class="profile-button" type="button" data-profile-button aria-haspopup="menu" aria-expanded="false" aria-controls="account-menu"><span class="profile-avatar" aria-hidden="true">${initials}</span><span class="sr-only">Open account menu</span><i class="ph ph-caret-down" aria-hidden="true"></i></button><div class="account-menu" id="account-menu" role="menu" data-account-menu hidden><div class="account-summary"><span class="profile-avatar is-large" aria-hidden="true">${initials}</span><div><strong>${esc(name)}</strong><span>${esc(email)}</span></div></div><div class="account-menu-divider"></div><button type="button" role="menuitem" data-open-account-dialog="profile-dialog"><i class="ph ph-user-circle" aria-hidden="true"></i><span>My Profile</span></button><button type="button" role="menuitem" data-open-account-dialog="preferences-dialog"><i class="ph ph-sliders-horizontal" aria-hidden="true"></i><span>Preferences</span></button><button type="button" role="menuitem" data-open-account-dialog="about-dialog"><i class="ph ph-info" aria-hidden="true"></i><span>About Ummiby Companion</span></button>${sessionAction}</div></div><dialog class="account-dialog" id="profile-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>My Profile</h2></div><button class="dialog-close" value="cancel" aria-label="Close profile"><i class="ph ph-x" aria-hidden="true"></i></button></div>${profileDetails}</form></dialog><dialog class="account-dialog" id="preferences-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>Preferences</h2></div><button class="dialog-close" value="cancel" aria-label="Close preferences"><i class="ph ph-x" aria-hidden="true"></i></button></div><div class="account-empty-state"><i class="ph ph-sliders-horizontal" aria-hidden="true"></i><h3>Your preferences will live here</h3><p>The account-preferences service is connected and ready for future user-controlled settings.</p></div></form></dialog><dialog class="account-dialog" id="about-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Application</p><h2>About Ummiby Companion</h2></div><button class="dialog-close" value="cancel" aria-label="Close about"><i class="ph ph-x" aria-hidden="true"></i></button></div><div class="about-mark" aria-hidden="true">U</div><dl class="account-details"><div><dt>Version</dt><dd>v${APP_VERSION}</dd></div><div><dt>Account connection</dt><dd>${configured?'Connected':'Preview mode'}</dd></div></dl></form></dialog>${isAuthenticated?`<dialog class="account-dialog is-confirmation" id="sign-out-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>Sign out?</h2></div><button class="dialog-close" value="cancel" aria-label="Cancel sign out"><i class="ph ph-x" aria-hidden="true"></i></button></div><p>You’ll return to the login screen. Your saved account data will remain available the next time you sign in.</p><div class="dialog-actions"><button class="button button-secondary" value="cancel">Cancel</button><button class="button button-danger" type="button" data-confirm-sign-out>Sign Out</button></div></form></dialog>`:''}`;
}

export function renderShell({pathname='/home',user=null,identity=null,configured=false}={}){const active=moduleForPath(pathname),view=viewName(active,pathname),reader=isReader(pathname),banner=bannerMeta(active,pathname);document.documentElement.dataset.theme=active.theme;document.title=`${view} | Ummiby Companion`;return `<div class="app-shell${reader?' is-reading':''}"><header class="brand-panel"><div class="brand-lockup"><div class="brand-mark" aria-hidden="true">U</div><p class="brand-name">Ummiby<br>Companion</p><p class="brand-version">v${APP_VERSION}</p></div></header><section class="module-banner${pathname==='/duaa'?' is-duaa-home-banner':''}${pathname==='/duaa/morning'?' is-duaa-morning-banner':''}${pathname==='/duaa/evening'?' is-duaa-evening-banner':''}${pathname==='/duaa/sleep'?' is-duaa-sleep-banner':''}${pathname==='/duaa/travel'?' is-duaa-travel-banner':''}${pathname==='/duaa/weather'?' is-duaa-weather-banner':''}${pathname==='/duaa/prayer'?' is-duaa-prayer-banner':''}${pathname==='/duaa/collections'?' is-duaa-collections-banner':''}${pathname==='/duaa/history'?' is-duaa-history-banner':''}${pathname==='/duaa/food'?' is-duaa-food-banner':''}${pathname==='/duaa/clothing'?' is-duaa-clothing-banner':''}${pathname==='/duaa/anxiety'?' is-duaa-anxiety-banner':''}"><div class="banner-copy"><p class="banner-eyebrow">${esc(banner.eyebrow)}</p><h1 class="banner-title">${esc(banner.title)}</h1><p class="banner-description">${esc(banner.description)}</p></div>${accountControls(user,identity,configured)}</section><aside class="app-sidebar">${sidebar(active)}</aside><main class="module-workspace">${reader?'':moduleNav(active,pathname)}<section class="module-content${active.id==='duaa'?' is-duaa-content':''}${reader?' is-reader-content':''}" id="module-content" tabindex="-1">${active.id==='duaa'?duaaContent(pathname):active.id==='quran'?quranContent(pathname):active.id==='ramadan'?ramadanContent(pathname):`<header class="page-header"><p class="page-kicker">${esc(active.label)}</p><h2 class="page-title">${esc(view)}</h2><p class="page-description">${esc(active.description)}</p></header><div class="card-grid">${placeholders(active)}</div>`}</section></main></div>`}
